WITH latest_match AS (SELECT s.*, latest.store_sale_revenue, latest.units FROM products s LEFT JOIN LATERAL (SELECT c.revenue AS store_sale_revenue, c.units FROM store_sales c WHERE c.product_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, product_name, price, stock_qty, tags, store_sale_revenue, units FROM latest_match ORDER BY stock_qty, store_sale_revenue;
